ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns lte http://soap.sforce.com/schemas/class/LTE_PortabilidadEntrante_ws
fun appendNamespace(data, nsSelector) =
  data match {
    case is Array -> data map appendNamespace($, nsSelector)
    case is Object -> data mapObject do {
      var ns0 = nsSelector
      ---
      if (ns0 != null) ns0#"$($$)": appendNamespace($, nsSelector)
      else ($$): appendNamespace($, nsSelector)
    }
    else -> data
}
---
{
soapenv#Envelope:{
    soapenv#Header:{
        lte#AllowFieldTruncationHeader:{
            lte#allowFieldTruncation:true
        },
        lte#SessionHeader:{
            lte#sessionId:vars.token_response.access_token default ""
        }
    },
    soapenv#Body: appendNamespace(payload, lte)
 }
}
